//! WHATWG HTML tokenizer (§13.2.5), with character reference decoding (§13.2.5.72–80) and the named character
//! reference table (§13.5, `html_entities.rs`, generated by `tools/gen_html_entities.py`).
//!
//! Spec: https://html.spec.whatwg.org/multipage/parsing.html#tokenization — §13.2.3.5 input stream preprocessing
//! (CR and CRLF become LF), §13.2.5 the tokenizer states and their transitions, §13.2.5.72–80 character references.
//! Tree construction (§13.2.6) is NOT implemented here; see docs/html.md.
//!
//! Errors are not reported; only tokens are produced. The tokenizer can be started in any state with a
//! "last start tag" name (used by the appropriate-end-tag checks), as the html5lib tokenizer tests require.

use crate::html_entities::NAMED;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Token {
    Doctype { name: Option<String>, public_id: Option<String>, system_id: Option<String>, force_quirks: bool },
    StartTag { name: String, attrs: Vec<(String, String)>, self_closing: bool },
    EndTag { name: String, attrs: Vec<(String, String)>, self_closing: bool },
    Comment(String),
    Character(char),
}

/// Tokenizer states (§13.2.5).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    Data,
    RcData,
    RawText,
    ScriptData,
    PlainText,
    TagOpen,
    EndTagOpen,
    TagName,
    RcDataLessThanSign,
    RcDataEndTagOpen,
    RcDataEndTagName,
    RawTextLessThanSign,
    RawTextEndTagOpen,
    RawTextEndTagName,
    ScriptDataLessThanSign,
    ScriptDataEndTagOpen,
    ScriptDataEndTagName,
    ScriptDataEscapeStart,
    ScriptDataEscapeStartDash,
    ScriptDataEscaped,
    ScriptDataEscapedDash,
    ScriptDataEscapedDashDash,
    ScriptDataEscapedLessThanSign,
    ScriptDataEscapedEndTagOpen,
    ScriptDataEscapedEndTagName,
    ScriptDataDoubleEscapeStart,
    ScriptDataDoubleEscaped,
    ScriptDataDoubleEscapedDash,
    ScriptDataDoubleEscapedDashDash,
    ScriptDataDoubleEscapedLessThanSign,
    ScriptDataDoubleEscapeEnd,
    BeforeAttributeName,
    AttributeName,
    AfterAttributeName,
    BeforeAttributeValue,
    AttributeValueDoubleQuoted,
    AttributeValueSingleQuoted,
    AttributeValueUnquoted,
    AfterAttributeValueQuoted,
    SelfClosingStartTag,
    BogusComment,
    MarkupDeclarationOpen,
    CommentStart,
    CommentStartDash,
    Comment,
    CommentLessThanSign,
    CommentLessThanSignBang,
    CommentLessThanSignBangDash,
    CommentLessThanSignBangDashDash,
    CommentEndDash,
    CommentEnd,
    CommentEndBang,
    Doctype,
    BeforeDoctypeName,
    DoctypeName,
    AfterDoctypeName,
    AfterDoctypePublicKeyword,
    BeforeDoctypePublicIdentifier,
    DoctypePublicIdentifierDoubleQuoted,
    DoctypePublicIdentifierSingleQuoted,
    AfterDoctypePublicIdentifier,
    BetweenDoctypePublicAndSystemIdentifiers,
    AfterDoctypeSystemKeyword,
    BeforeDoctypeSystemIdentifier,
    DoctypeSystemIdentifierDoubleQuoted,
    DoctypeSystemIdentifierSingleQuoted,
    AfterDoctypeSystemIdentifier,
    BogusDoctype,
    CharacterReference,
    NamedCharacterReference,
    AmbiguousAmpersand,
    NumericCharacterReference,
    HexadecimalCharacterReferenceStart,
    DecimalCharacterReferenceStart,
    HexadecimalCharacterReference,
    DecimalCharacterReference,
    NumericCharacterReferenceEnd,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Cur {
    Char(char),
    Eof,
}

#[derive(Default, Clone)]
struct TagBuild {
    name: String,
    attrs: Vec<(String, String)>,
    self_closing: bool,
    is_end: bool,
}

#[derive(Default, Clone)]
struct DoctypeBuild {
    name: Option<String>,
    public_id: Option<String>,
    system_id: Option<String>,
    force_quirks: bool,
}

/// The tokenizer. Input is preprocessed on construction (§13.2.3.5).
pub struct Tokenizer {
    input: Vec<char>,
    pos: usize,
    state: State,
    return_state: State,
    temp: String,
    tag: TagBuild,
    comment: String,
    doctype: DoctypeBuild,
    attr_name: String,
    attr_value: String,
    last_start_tag: String,
    char_ref_code: u32,
    reconsume: bool,
    last: Cur,
    out: std::collections::VecDeque<Token>,
    eof: bool,
}

const REPLACEMENT: char = '\u{FFFD}';

fn is_ws(c: char) -> bool {
    matches!(c, '\t' | '\n' | '\u{0C}' | ' ')
}

impl Tokenizer {
    pub fn new(input: &str) -> Tokenizer {
        // §13.2.3.5: CR LF and lone CR are normalised to LF.
        let mut chars = Vec::with_capacity(input.len());
        let mut it = input.chars().peekable();
        while let Some(c) = it.next() {
            if c == '\r' {
                if it.peek() == Some(&'\n') {
                    it.next();
                }
                chars.push('\n');
            } else {
                chars.push(c);
            }
        }
        Tokenizer {
            input: chars,
            pos: 0,
            state: State::Data,
            return_state: State::Data,
            temp: String::new(),
            tag: TagBuild::default(),
            comment: String::new(),
            doctype: DoctypeBuild::default(),
            attr_name: String::new(),
            attr_value: String::new(),
            last_start_tag: String::new(),
            char_ref_code: 0,
            reconsume: false,
            last: Cur::Eof,
            out: std::collections::VecDeque::new(),
            eof: false,
        }
    }

    /// Start in `state`, with `last_start_tag` as the most recent start tag name (may be empty).
    pub fn with_state(input: &str, state: State, last_start_tag: &str) -> Tokenizer {
        let mut t = Tokenizer::new(input);
        t.state = state;
        t.last_start_tag = last_start_tag.to_string();
        t
    }

    /// Next token, or None at end of input.
    pub fn next_token(&mut self) -> Option<Token> {
        loop {
            if let Some(t) = self.out.pop_front() {
                return Some(t);
            }
            if self.eof {
                return None;
            }
            self.step();
        }
    }

    /// All tokens of the input (for tests and simple callers).
    pub fn all_tokens(input: &str, state: State, last_start_tag: &str) -> Vec<Token> {
        let mut t = Tokenizer::with_state(input, state, last_start_tag);
        let mut v = Vec::new();
        while let Some(tok) = t.next_token() {
            v.push(tok);
        }
        v
    }

    // ---- input helpers --------------------------------------------------------------------------------------

    fn consume(&mut self) -> Cur {
        if self.reconsume {
            self.reconsume = false;
            return self.last;
        }
        self.last = match self.input.get(self.pos) {
            Some(&c) => Cur::Char(c),
            None => Cur::Eof,
        };
        self.pos += 1;
        self.last
    }

    fn reconsume_in(&mut self, s: State) {
        self.state = s;
        self.reconsume = true;
    }

    fn emit(&mut self, t: Token) {
        self.out.push_back(t);
    }

    fn emit_char(&mut self, c: char) {
        self.out.push_back(Token::Character(c));
    }

    fn emit_str(&mut self, s: &str) {
        for c in s.chars() {
            self.emit_char(c);
        }
    }

    fn emit_eof(&mut self) {
        self.eof = true;
    }

    fn lookahead_matches_ci(&self, s: &str) -> bool {
        let n = s.chars().count();
        if self.pos + n > self.input.len() {
            return false;
        }
        self.input[self.pos..self.pos + n].iter().zip(s.chars()).all(|(a, b)| a.to_ascii_uppercase() == b.to_ascii_uppercase())
    }

    fn start_new_attribute(&mut self) {
        if !self.attr_name.is_empty() {
            self.finish_attribute();
        }
        self.attr_name.clear();
        self.attr_value.clear();
    }

    /// Store the attribute being built unless its name is a duplicate (first one wins).
    fn finish_attribute(&mut self) {
        let name = std::mem::take(&mut self.attr_name);
        let value = std::mem::take(&mut self.attr_value);
        if !self.tag.attrs.iter().any(|(n, _)| *n == name) {
            self.tag.attrs.push((name, value));
        }
    }

    fn take_tag_token(&mut self) -> Token {
        if !self.attr_name.is_empty() {
            self.finish_attribute();
        }
        let tb = std::mem::take(&mut self.tag);
        if tb.is_end {
            Token::EndTag { name: tb.name, attrs: tb.attrs, self_closing: tb.self_closing }
        } else {
            self.last_start_tag = tb.name.clone();
            Token::StartTag { name: tb.name, attrs: tb.attrs, self_closing: tb.self_closing }
        }
    }

    /// Append to the current attribute value or emit, depending on whether a character reference is returning
    /// into an attribute (§13.2.5.72 "flush code points consumed as a character reference").
    fn flush_text(&mut self, s: &str) {
        if self.return_state_is_attribute() {
            self.attr_value.push_str(s);
        } else {
            for c in s.chars() {
                self.emit_char(c);
            }
        }
    }

    fn return_state_is_attribute(&self) -> bool {
        matches!(self.return_state, State::AttributeValueDoubleQuoted | State::AttributeValueSingleQuoted | State::AttributeValueUnquoted)
    }

    fn appropriate_end_tag(&self, name: &str) -> bool {
        !self.last_start_tag.is_empty() && self.last_start_tag == name
    }

    // ---- the state machine ------------------------------------------------------------------------------------

    fn step(&mut self) {
        // States that do not consume a character up front (they inspect the input at the current position).
        if self.state == State::MarkupDeclarationOpen {
            self.markup_declaration_open();
            return;
        }
        if self.state == State::NamedCharacterReference {
            self.named_reference();
            return;
        }
        let c = self.consume();
        match self.state {
            State::Data => match c {
                Cur::Char('&') => {
                    self.return_state = State::Data;
                    self.state = State::CharacterReference;
                }
                Cur::Char('<') => self.state = State::TagOpen,
                Cur::Char('\0') => self.emit_char('\0'),
                Cur::Char(ch) => self.emit_char(ch),
                Cur::Eof => self.emit_eof(),
            },
            State::RcData => match c {
                Cur::Char('&') => {
                    self.return_state = State::RcData;
                    self.state = State::CharacterReference;
                }
                Cur::Char('<') => self.state = State::RcDataLessThanSign,
                Cur::Char('\0') => self.emit_char(REPLACEMENT),
                Cur::Char(ch) => self.emit_char(ch),
                Cur::Eof => self.emit_eof(),
            },
            State::RawText => match c {
                Cur::Char('<') => self.state = State::RawTextLessThanSign,
                Cur::Char('\0') => self.emit_char(REPLACEMENT),
                Cur::Char(ch) => self.emit_char(ch),
                Cur::Eof => self.emit_eof(),
            },
            State::ScriptData => match c {
                Cur::Char('<') => self.state = State::ScriptDataLessThanSign,
                Cur::Char('\0') => self.emit_char(REPLACEMENT),
                Cur::Char(ch) => self.emit_char(ch),
                Cur::Eof => self.emit_eof(),
            },
            State::PlainText => match c {
                Cur::Char('\0') => self.emit_char(REPLACEMENT),
                Cur::Char(ch) => self.emit_char(ch),
                Cur::Eof => self.emit_eof(),
            },
            State::TagOpen => match c {
                Cur::Char('!') => self.state = State::MarkupDeclarationOpen,
                Cur::Char('/') => self.state = State::EndTagOpen,
                Cur::Char(ch) if ch.is_ascii_alphabetic() => {
                    self.tag = TagBuild { is_end: false, ..Default::default() };
                    self.reconsume_in(State::TagName);
                }
                Cur::Char('?') => {
                    self.comment.clear();
                    self.reconsume_in(State::BogusComment);
                }
                Cur::Eof => {
                    self.emit_char('<');
                    self.emit_eof();
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume_in(State::Data);
                }
            },
            State::EndTagOpen => match c {
                Cur::Char(ch) if ch.is_ascii_alphabetic() => {
                    self.tag = TagBuild { is_end: true, ..Default::default() };
                    self.reconsume_in(State::TagName);
                }
                Cur::Char('>') => self.state = State::Data,
                Cur::Eof => {
                    self.emit_str("</");
                    self.emit_eof();
                }
                _ => {
                    self.comment.clear();
                    self.reconsume_in(State::BogusComment);
                }
            },
            State::TagName => match c {
                Cur::Char(ch) if is_ws(ch) => self.state = State::BeforeAttributeName,
                Cur::Char('/') => self.state = State::SelfClosingStartTag,
                Cur::Char('>') => {
                    let t = self.take_tag_token();
                    self.emit(t);
                    self.state = State::Data;
                }
                Cur::Char('\0') => self.tag.name.push(REPLACEMENT),
                Cur::Char(ch) => self.tag.name.push(ch.to_ascii_lowercase()),
                Cur::Eof => self.emit_eof(),
            },
            State::RcDataLessThanSign => match c {
                Cur::Char('/') => {
                    self.temp.clear();
                    self.state = State::RcDataEndTagOpen;
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume_in(State::RcData);
                }
            },
            State::RcDataEndTagOpen => self.end_tag_open(c, State::RcDataEndTagName, State::RcData),
            State::RcDataEndTagName => self.end_tag_name(c, State::RcData),
            State::RawTextLessThanSign => match c {
                Cur::Char('/') => {
                    self.temp.clear();
                    self.state = State::RawTextEndTagOpen;
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume_in(State::RawText);
                }
            },
            State::RawTextEndTagOpen => self.end_tag_open(c, State::RawTextEndTagName, State::RawText),
            State::RawTextEndTagName => self.end_tag_name(c, State::RawText),
            State::ScriptDataLessThanSign => match c {
                Cur::Char('/') => {
                    self.temp.clear();
                    self.state = State::ScriptDataEndTagOpen;
                }
                Cur::Char('!') => {
                    self.state = State::ScriptDataEscapeStart;
                    self.emit_str("<!");
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume_in(State::ScriptData);
                }
            },
            State::ScriptDataEndTagOpen => self.end_tag_open(c, State::ScriptDataEndTagName, State::ScriptData),
            State::ScriptDataEndTagName => self.end_tag_name(c, State::ScriptData),
            State::ScriptDataEscapeStart => match c {
                Cur::Char('-') => {
                    self.state = State::ScriptDataEscapeStartDash;
                    self.emit_char('-');
                }
                _ => self.reconsume_in(State::ScriptData),
            },
            State::ScriptDataEscapeStartDash => match c {
                Cur::Char('-') => {
                    self.state = State::ScriptDataEscapedDashDash;
                    self.emit_char('-');
                }
                _ => self.reconsume_in(State::ScriptData),
            },
            State::ScriptDataEscaped => match c {
                Cur::Char('-') => {
                    self.state = State::ScriptDataEscapedDash;
                    self.emit_char('-');
                }
                Cur::Char('<') => self.state = State::ScriptDataEscapedLessThanSign,
                Cur::Char('\0') => self.emit_char(REPLACEMENT),
                Cur::Char(ch) => self.emit_char(ch),
                Cur::Eof => self.emit_eof(),
            },
            State::ScriptDataEscapedDash => match c {
                Cur::Char('-') => {
                    self.state = State::ScriptDataEscapedDashDash;
                    self.emit_char('-');
                }
                Cur::Char('<') => self.state = State::ScriptDataEscapedLessThanSign,
                Cur::Char('\0') => {
                    self.state = State::ScriptDataEscaped;
                    self.emit_char(REPLACEMENT);
                }
                Cur::Char(ch) => {
                    self.state = State::ScriptDataEscaped;
                    self.emit_char(ch);
                }
                Cur::Eof => self.emit_eof(),
            },
            State::ScriptDataEscapedDashDash => match c {
                Cur::Char('-') => self.emit_char('-'),
                Cur::Char('<') => self.state = State::ScriptDataEscapedLessThanSign,
                Cur::Char('>') => {
                    self.state = State::ScriptData;
                    self.emit_char('>');
                }
                Cur::Char('\0') => {
                    self.state = State::ScriptDataEscaped;
                    self.emit_char(REPLACEMENT);
                }
                Cur::Char(ch) => {
                    self.state = State::ScriptDataEscaped;
                    self.emit_char(ch);
                }
                Cur::Eof => self.emit_eof(),
            },
            State::ScriptDataEscapedLessThanSign => match c {
                Cur::Char('/') => {
                    self.temp.clear();
                    self.state = State::ScriptDataEscapedEndTagOpen;
                }
                Cur::Char(ch) if ch.is_ascii_alphabetic() => {
                    self.temp.clear();
                    self.emit_char('<');
                    self.reconsume_in(State::ScriptDataDoubleEscapeStart);
                }
                _ => {
                    self.emit_char('<');
                    self.reconsume_in(State::ScriptDataEscaped);
                }
            },
            State::ScriptDataEscapedEndTagOpen => self.end_tag_open(c, State::ScriptDataEscapedEndTagName, State::ScriptDataEscaped),
            State::ScriptDataEscapedEndTagName => self.end_tag_name(c, State::ScriptDataEscaped),
            State::ScriptDataDoubleEscapeStart => match c {
                Cur::Char(ch) if is_ws(ch) || ch == '/' || ch == '>' => {
                    self.state = if self.temp == "script" { State::ScriptDataDoubleEscaped } else { State::ScriptDataEscaped };
                    self.emit_char(ch);
                }
                Cur::Char(ch) if ch.is_ascii_alphabetic() => {
                    self.temp.push(ch.to_ascii_lowercase());
                    self.emit_char(ch);
                }
                _ => self.reconsume_in(State::ScriptDataEscaped),
            },
            State::ScriptDataDoubleEscaped => match c {
                Cur::Char('-') => {
                    self.state = State::ScriptDataDoubleEscapedDash;
                    self.emit_char('-');
                }
                Cur::Char('<') => {
                    self.state = State::ScriptDataDoubleEscapedLessThanSign;
                    self.emit_char('<');
                }
                Cur::Char('\0') => self.emit_char(REPLACEMENT),
                Cur::Char(ch) => self.emit_char(ch),
                Cur::Eof => self.emit_eof(),
            },
            State::ScriptDataDoubleEscapedDash => match c {
                Cur::Char('-') => {
                    self.state = State::ScriptDataDoubleEscapedDashDash;
                    self.emit_char('-');
                }
                Cur::Char('<') => {
                    self.state = State::ScriptDataDoubleEscapedLessThanSign;
                    self.emit_char('<');
                }
                Cur::Char('\0') => {
                    self.state = State::ScriptDataDoubleEscaped;
                    self.emit_char(REPLACEMENT);
                }
                Cur::Char(ch) => {
                    self.state = State::ScriptDataDoubleEscaped;
                    self.emit_char(ch);
                }
                Cur::Eof => self.emit_eof(),
            },
            State::ScriptDataDoubleEscapedDashDash => match c {
                Cur::Char('-') => self.emit_char('-'),
                Cur::Char('<') => {
                    self.state = State::ScriptDataDoubleEscapedLessThanSign;
                    self.emit_char('<');
                }
                Cur::Char('>') => {
                    self.state = State::ScriptData;
                    self.emit_char('>');
                }
                Cur::Char('\0') => {
                    self.state = State::ScriptDataDoubleEscaped;
                    self.emit_char(REPLACEMENT);
                }
                Cur::Char(ch) => {
                    self.state = State::ScriptDataDoubleEscaped;
                    self.emit_char(ch);
                }
                Cur::Eof => self.emit_eof(),
            },
            State::ScriptDataDoubleEscapedLessThanSign => match c {
                Cur::Char('/') => {
                    self.temp.clear();
                    self.state = State::ScriptDataDoubleEscapeEnd;
                    self.emit_char('/');
                }
                _ => self.reconsume_in(State::ScriptDataDoubleEscaped),
            },
            State::ScriptDataDoubleEscapeEnd => match c {
                Cur::Char(ch) if is_ws(ch) || ch == '/' || ch == '>' => {
                    self.state = if self.temp == "script" { State::ScriptDataEscaped } else { State::ScriptDataDoubleEscaped };
                    self.emit_char(ch);
                }
                Cur::Char(ch) if ch.is_ascii_alphabetic() => {
                    self.temp.push(ch.to_ascii_lowercase());
                    self.emit_char(ch);
                }
                _ => self.reconsume_in(State::ScriptDataDoubleEscaped),
            },
            State::BeforeAttributeName => match c {
                Cur::Char(ch) if is_ws(ch) => {}
                Cur::Char('/') | Cur::Char('>') | Cur::Eof => self.reconsume_in(State::AfterAttributeName),
                Cur::Char('=') => {
                    self.start_new_attribute();
                    self.attr_name.push('=');
                    self.state = State::AttributeName;
                }
                _ => {
                    self.start_new_attribute();
                    self.reconsume_in(State::AttributeName);
                }
            },
            State::AttributeName => match c {
                Cur::Char(ch) if is_ws(ch) || ch == '/' || ch == '>' => self.reconsume_in(State::AfterAttributeName),
                Cur::Eof => self.reconsume_in(State::AfterAttributeName),
                Cur::Char('=') => self.state = State::BeforeAttributeValue,
                Cur::Char(ch) => self.attr_name.push(if ch == '\0' { REPLACEMENT } else { ch.to_ascii_lowercase() }),
            },
            State::AfterAttributeName => match c {
                Cur::Char(ch) if is_ws(ch) => {}
                Cur::Char('/') => self.state = State::SelfClosingStartTag,
                Cur::Char('=') => self.state = State::BeforeAttributeValue,
                Cur::Char('>') => {
                    let t = self.take_tag_token();
                    self.emit(t);
                    self.state = State::Data;
                }
                Cur::Eof => self.emit_eof(),
                _ => {
                    self.start_new_attribute();
                    self.reconsume_in(State::AttributeName);
                }
            },
            State::BeforeAttributeValue => match c {
                Cur::Char(ch) if is_ws(ch) => {}
                Cur::Char('"') => self.state = State::AttributeValueDoubleQuoted,
                Cur::Char('\'') => self.state = State::AttributeValueSingleQuoted,
                Cur::Char('>') => {
                    let t = self.take_tag_token();
                    self.emit(t);
                    self.state = State::Data;
                }
                _ => self.reconsume_in(State::AttributeValueUnquoted),
            },
            State::AttributeValueDoubleQuoted => self.attr_value_quoted(c, '"'),
            State::AttributeValueSingleQuoted => self.attr_value_quoted(c, '\''),
            State::AttributeValueUnquoted => match c {
                Cur::Char(ch) if is_ws(ch) => self.state = State::BeforeAttributeName,
                Cur::Char('&') => {
                    self.return_state = State::AttributeValueUnquoted;
                    self.state = State::CharacterReference;
                }
                Cur::Char('>') => {
                    let t = self.take_tag_token();
                    self.emit(t);
                    self.state = State::Data;
                }
                Cur::Char('\0') => self.attr_value.push(REPLACEMENT),
                Cur::Char(ch) => self.attr_value.push(ch),
                Cur::Eof => self.emit_eof(),
            },
            State::AfterAttributeValueQuoted => match c {
                Cur::Char(ch) if is_ws(ch) => self.state = State::BeforeAttributeName,
                Cur::Char('/') => self.state = State::SelfClosingStartTag,
                Cur::Char('>') => {
                    let t = self.take_tag_token();
                    self.emit(t);
                    self.state = State::Data;
                }
                Cur::Eof => self.emit_eof(),
                _ => self.reconsume_in(State::BeforeAttributeName),
            },
            State::SelfClosingStartTag => match c {
                Cur::Char('>') => {
                    self.tag.self_closing = true;
                    let t = self.take_tag_token();
                    self.emit(t);
                    self.state = State::Data;
                }
                Cur::Eof => self.emit_eof(),
                _ => self.reconsume_in(State::BeforeAttributeName),
            },
            State::BogusComment => match c {
                Cur::Char('>') => {
                    let s = std::mem::take(&mut self.comment);
                    self.emit(Token::Comment(s));
                    self.state = State::Data;
                }
                Cur::Eof => {
                    let s = std::mem::take(&mut self.comment);
                    self.emit(Token::Comment(s));
                    self.emit_eof();
                }
                Cur::Char('\0') => self.comment.push(REPLACEMENT),
                Cur::Char(ch) => self.comment.push(ch),
            },
            State::MarkupDeclarationOpen => self.markup_declaration_open(),
            State::CommentStart => match c {
                Cur::Char('-') => self.state = State::CommentStartDash,
                Cur::Char('>') => {
                    let s = std::mem::take(&mut self.comment);
                    self.emit(Token::Comment(s));
                    self.state = State::Data;
                }
                _ => self.reconsume_in(State::Comment),
            },
            State::CommentStartDash => match c {
                Cur::Char('-') => self.state = State::CommentEnd,
                Cur::Char('>') => {
                    let s = std::mem::take(&mut self.comment);
                    self.emit(Token::Comment(s));
                    self.state = State::Data;
                }
                Cur::Eof => {
                    let s = std::mem::take(&mut self.comment);
                    self.emit(Token::Comment(s));
                    self.emit_eof();
                }
                _ => {
                    self.comment.push('-');
                    self.reconsume_in(State::Comment);
                }
            },
            State::Comment => match c {
                Cur::Char('<') => {
                    self.comment.push('<');
                    self.state = State::CommentLessThanSign;
                }
                Cur::Char('-') => self.state = State::CommentEndDash,
                Cur::Char('\0') => self.comment.push(REPLACEMENT),
                Cur::Char(ch) => self.comment.push(ch),
                Cur::Eof => {
                    let s = std::mem::take(&mut self.comment);
                    self.emit(Token::Comment(s));
                    self.emit_eof();
                }
            },
            State::CommentLessThanSign => match c {
                Cur::Char('!') => {
                    self.comment.push('!');
                    self.state = State::CommentLessThanSignBang;
                }
                Cur::Char('<') => self.comment.push('<'),
                _ => self.reconsume_in(State::Comment),
            },
            State::CommentLessThanSignBang => match c {
                Cur::Char('-') => self.state = State::CommentLessThanSignBangDash,
                _ => self.reconsume_in(State::Comment),
            },
            State::CommentLessThanSignBangDash => match c {
                Cur::Char('-') => self.state = State::CommentLessThanSignBangDashDash,
                _ => self.reconsume_in(State::CommentEndDash),
            },
            State::CommentLessThanSignBangDashDash => match c {
                Cur::Char('>') | Cur::Eof => self.reconsume_in(State::CommentEnd),
                _ => self.reconsume_in(State::CommentEnd),
            },
            State::CommentEndDash => match c {
                Cur::Char('-') => self.state = State::CommentEnd,
                Cur::Eof => {
                    let s = std::mem::take(&mut self.comment);
                    self.emit(Token::Comment(s));
                    self.emit_eof();
                }
                _ => {
                    self.comment.push('-');
                    self.reconsume_in(State::Comment);
                }
            },
            State::CommentEnd => match c {
                Cur::Char('>') => {
                    let s = std::mem::take(&mut self.comment);
                    self.emit(Token::Comment(s));
                    self.state = State::Data;
                }
                Cur::Char('!') => self.state = State::CommentEndBang,
                Cur::Char('-') => self.comment.push('-'),
                Cur::Eof => {
                    let s = std::mem::take(&mut self.comment);
                    self.emit(Token::Comment(s));
                    self.emit_eof();
                }
                _ => {
                    self.comment.push_str("--");
                    self.reconsume_in(State::Comment);
                }
            },
            State::CommentEndBang => match c {
                Cur::Char('-') => {
                    self.comment.push_str("--!");
                    self.state = State::CommentEndDash;
                }
                Cur::Char('>') => {
                    let s = std::mem::take(&mut self.comment);
                    self.emit(Token::Comment(s));
                    self.state = State::Data;
                }
                Cur::Eof => {
                    let s = std::mem::take(&mut self.comment);
                    self.emit(Token::Comment(s));
                    self.emit_eof();
                }
                _ => {
                    self.comment.push_str("--!");
                    self.reconsume_in(State::Comment);
                }
            },
            State::Doctype => match c {
                Cur::Char(ch) if is_ws(ch) => self.state = State::BeforeDoctypeName,
                Cur::Char('>') => self.reconsume_in(State::BeforeDoctypeName),
                Cur::Eof => {
                    self.doctype = DoctypeBuild { force_quirks: true, ..Default::default() };
                    self.emit_doctype();
                    self.emit_eof();
                }
                _ => self.reconsume_in(State::BeforeDoctypeName),
            },
            State::BeforeDoctypeName => match c {
                Cur::Char(ch) if is_ws(ch) => {}
                Cur::Char('\0') => {
                    self.doctype = DoctypeBuild { name: Some(REPLACEMENT.to_string()), ..Default::default() };
                    self.state = State::DoctypeName;
                }
                Cur::Char('>') => {
                    self.doctype = DoctypeBuild { force_quirks: true, ..Default::default() };
                    self.emit_doctype();
                    self.state = State::Data;
                }
                Cur::Eof => {
                    self.doctype = DoctypeBuild { force_quirks: true, ..Default::default() };
                    self.emit_doctype();
                    self.emit_eof();
                }
                Cur::Char(ch) => {
                    self.doctype = DoctypeBuild { name: Some(ch.to_ascii_lowercase().to_string()), ..Default::default() };
                    self.state = State::DoctypeName;
                }
            },
            State::DoctypeName => match c {
                Cur::Char(ch) if is_ws(ch) => self.state = State::AfterDoctypeName,
                Cur::Char('>') => {
                    self.emit_doctype();
                    self.state = State::Data;
                }
                Cur::Char(ch) => {
                    let n = self.doctype.name.get_or_insert_with(String::new);
                    n.push(if ch == '\0' { REPLACEMENT } else { ch.to_ascii_lowercase() });
                }
                Cur::Eof => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
            },
            State::AfterDoctypeName => match c {
                Cur::Char(ch) if is_ws(ch) => {}
                Cur::Char('>') => {
                    self.emit_doctype();
                    self.state = State::Data;
                }
                Cur::Eof => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                _ => {
                    // Step back over the character just consumed so the keyword lookahead starts at it.
                    self.pos -= 1;
                    if self.lookahead_matches_ci("PUBLIC") {
                        self.pos += 6;
                        self.state = State::AfterDoctypePublicKeyword;
                    } else if self.lookahead_matches_ci("SYSTEM") {
                        self.pos += 6;
                        self.state = State::AfterDoctypeSystemKeyword;
                    } else {
                        self.doctype.force_quirks = true;
                        self.state = State::BogusDoctype;
                    }
                }
            },
            State::AfterDoctypePublicKeyword => match c {
                Cur::Char(ch) if is_ws(ch) => self.state = State::BeforeDoctypePublicIdentifier,
                Cur::Char('"') => {
                    self.doctype.public_id = Some(String::new());
                    self.state = State::DoctypePublicIdentifierDoubleQuoted;
                }
                Cur::Char('\'') => {
                    self.doctype.public_id = Some(String::new());
                    self.state = State::DoctypePublicIdentifierSingleQuoted;
                }
                Cur::Char('>') => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.state = State::Data;
                }
                Cur::Eof => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                _ => {
                    self.doctype.force_quirks = true;
                    self.reconsume_in(State::BogusDoctype);
                }
            },
            State::BeforeDoctypePublicIdentifier => match c {
                Cur::Char(ch) if is_ws(ch) => {}
                Cur::Char('"') => {
                    self.doctype.public_id = Some(String::new());
                    self.state = State::DoctypePublicIdentifierDoubleQuoted;
                }
                Cur::Char('\'') => {
                    self.doctype.public_id = Some(String::new());
                    self.state = State::DoctypePublicIdentifierSingleQuoted;
                }
                Cur::Char('>') => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.state = State::Data;
                }
                Cur::Eof => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                _ => {
                    self.doctype.force_quirks = true;
                    self.reconsume_in(State::BogusDoctype);
                }
            },
            State::DoctypePublicIdentifierDoubleQuoted => self.doctype_quoted(c, '"', true),
            State::DoctypePublicIdentifierSingleQuoted => self.doctype_quoted(c, '\'', true),
            State::AfterDoctypePublicIdentifier => match c {
                Cur::Char(ch) if is_ws(ch) => self.state = State::BetweenDoctypePublicAndSystemIdentifiers,
                Cur::Char('>') => {
                    self.emit_doctype();
                    self.state = State::Data;
                }
                Cur::Char('"') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = State::DoctypeSystemIdentifierDoubleQuoted;
                }
                Cur::Char('\'') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = State::DoctypeSystemIdentifierSingleQuoted;
                }
                Cur::Eof => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                _ => {
                    self.doctype.force_quirks = true;
                    self.reconsume_in(State::BogusDoctype);
                }
            },
            State::BetweenDoctypePublicAndSystemIdentifiers => match c {
                Cur::Char(ch) if is_ws(ch) => {}
                Cur::Char('>') => {
                    self.emit_doctype();
                    self.state = State::Data;
                }
                Cur::Char('"') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = State::DoctypeSystemIdentifierDoubleQuoted;
                }
                Cur::Char('\'') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = State::DoctypeSystemIdentifierSingleQuoted;
                }
                Cur::Eof => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                _ => {
                    self.doctype.force_quirks = true;
                    self.reconsume_in(State::BogusDoctype);
                }
            },
            State::AfterDoctypeSystemKeyword => match c {
                Cur::Char(ch) if is_ws(ch) => self.state = State::BeforeDoctypeSystemIdentifier,
                Cur::Char('"') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = State::DoctypeSystemIdentifierDoubleQuoted;
                }
                Cur::Char('\'') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = State::DoctypeSystemIdentifierSingleQuoted;
                }
                Cur::Char('>') => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.state = State::Data;
                }
                Cur::Eof => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                _ => {
                    self.doctype.force_quirks = true;
                    self.reconsume_in(State::BogusDoctype);
                }
            },
            State::BeforeDoctypeSystemIdentifier => match c {
                Cur::Char(ch) if is_ws(ch) => {}
                Cur::Char('"') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = State::DoctypeSystemIdentifierDoubleQuoted;
                }
                Cur::Char('\'') => {
                    self.doctype.system_id = Some(String::new());
                    self.state = State::DoctypeSystemIdentifierSingleQuoted;
                }
                Cur::Char('>') => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.state = State::Data;
                }
                Cur::Eof => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                _ => {
                    self.doctype.force_quirks = true;
                    self.reconsume_in(State::BogusDoctype);
                }
            },
            State::DoctypeSystemIdentifierDoubleQuoted => self.doctype_quoted(c, '"', false),
            State::DoctypeSystemIdentifierSingleQuoted => self.doctype_quoted(c, '\'', false),
            State::AfterDoctypeSystemIdentifier => match c {
                Cur::Char(ch) if is_ws(ch) => {}
                Cur::Char('>') => {
                    self.emit_doctype();
                    self.state = State::Data;
                }
                Cur::Eof => {
                    self.doctype.force_quirks = true;
                    self.emit_doctype();
                    self.emit_eof();
                }
                _ => self.reconsume_in(State::BogusDoctype),
            },
            State::BogusDoctype => match c {
                Cur::Char('>') => {
                    self.emit_doctype();
                    self.state = State::Data;
                }
                Cur::Eof => {
                    self.emit_doctype();
                    self.emit_eof();
                }
                _ => {}
            },
            State::CharacterReference => {
                self.temp.clear();
                self.temp.push('&');
                match c {
                    Cur::Char(ch) if ch.is_ascii_alphanumeric() => {
                        self.pos -= 1;
                        self.state = State::NamedCharacterReference;
                    }
                    Cur::Char('#') => {
                        self.temp.push('#');
                        self.state = State::NumericCharacterReference;
                    }
                    _ => {
                        let t = std::mem::take(&mut self.temp);
                        self.flush_text(&t);
                        self.reconsume_in(self.return_state);
                    }
                }
            }
            State::NamedCharacterReference => self.named_reference(),
            State::AmbiguousAmpersand => match c {
                Cur::Char(ch) if ch.is_ascii_alphanumeric() => {
                    if self.return_state_is_attribute() {
                        self.attr_value.push(ch);
                    } else {
                        self.emit_char(ch);
                    }
                }
                Cur::Char(';') => self.reconsume_in(self.return_state),
                _ => self.reconsume_in(self.return_state),
            },
            State::NumericCharacterReference => {
                self.char_ref_code = 0;
                match c {
                    Cur::Char(ch @ ('x' | 'X')) => {
                        self.temp.push(ch);
                        self.state = State::HexadecimalCharacterReferenceStart;
                    }
                    _ => self.reconsume_in(State::DecimalCharacterReferenceStart),
                }
            }
            State::HexadecimalCharacterReferenceStart => match c {
                Cur::Char(ch) if ch.is_ascii_hexdigit() => self.reconsume_in(State::HexadecimalCharacterReference),
                _ => {
                    let t = std::mem::take(&mut self.temp);
                    self.flush_text(&t);
                    self.reconsume_in(self.return_state);
                }
            },
            State::DecimalCharacterReferenceStart => match c {
                Cur::Char(ch) if ch.is_ascii_digit() => self.reconsume_in(State::DecimalCharacterReference),
                _ => {
                    let t = std::mem::take(&mut self.temp);
                    self.flush_text(&t);
                    self.reconsume_in(self.return_state);
                }
            },
            State::HexadecimalCharacterReference => match c {
                Cur::Char(ch) if ch.is_ascii_hexdigit() => {
                    self.char_ref_code = self.char_ref_code.saturating_mul(16).saturating_add(ch.to_digit(16).unwrap());
                }
                Cur::Char(';') => self.state = State::NumericCharacterReferenceEnd,
                _ => self.reconsume_in(State::NumericCharacterReferenceEnd),
            },
            State::DecimalCharacterReference => match c {
                Cur::Char(ch) if ch.is_ascii_digit() => {
                    self.char_ref_code = self.char_ref_code.saturating_mul(10).saturating_add(ch.to_digit(10).unwrap());
                }
                Cur::Char(';') => self.state = State::NumericCharacterReferenceEnd,
                _ => self.reconsume_in(State::NumericCharacterReferenceEnd),
            },
            State::NumericCharacterReferenceEnd => {
                // §13.2.5.80: replacement table for C1 controls, and invalid code points.
                let code = self.char_ref_code;
                let ch = match code {
                    0 => REPLACEMENT,
                    c if c > 0x10FFFF => REPLACEMENT,
                    0xD800..=0xDFFF => REPLACEMENT,
                    c if (0x80..=0x9F).contains(&c) => c1_replacement(c),
                    c => char::from_u32(c).unwrap_or(REPLACEMENT),
                };
                self.temp.clear();
                let s = ch.to_string();
                self.flush_text(&s);
                self.reconsume_in(self.return_state);
                self.state = self.return_state;
            }
        }
    }

    fn markup_declaration_open(&mut self) {
        if self.lookahead_matches_ci("--") {
            self.pos += 2;
            self.comment.clear();
            self.state = State::CommentStart;
        } else if self.lookahead_matches_ci("DOCTYPE") {
            self.pos += 7;
            self.state = State::Doctype;
        } else {
            // No adjusted current node in the tokenizer-only setting: "[CDATA[" is a bogus comment.
            self.comment.clear();
            self.state = State::BogusComment;
        }
    }

    fn emit_doctype(&mut self) {
        let d = std::mem::take(&mut self.doctype);
        self.emit(Token::Doctype { name: d.name, public_id: d.public_id, system_id: d.system_id, force_quirks: d.force_quirks });
    }

    fn doctype_quoted(&mut self, c: Cur, quote: char, public: bool) {
        match c {
            Cur::Char(ch) if ch == quote => {
                self.state = if public { State::AfterDoctypePublicIdentifier } else { State::AfterDoctypeSystemIdentifier };
            }
            Cur::Char('\0') => self.push_doctype_id(public, REPLACEMENT),
            Cur::Char('>') => {
                self.doctype.force_quirks = true;
                self.emit_doctype();
                self.state = State::Data;
            }
            Cur::Eof => {
                self.doctype.force_quirks = true;
                self.emit_doctype();
                self.emit_eof();
            }
            Cur::Char(ch) => self.push_doctype_id(public, ch),
        }
    }

    fn push_doctype_id(&mut self, public: bool, ch: char) {
        let slot = if public { &mut self.doctype.public_id } else { &mut self.doctype.system_id };
        slot.get_or_insert_with(String::new).push(ch);
    }

    fn attr_value_quoted(&mut self, c: Cur, quote: char) {
        match c {
            Cur::Char(ch) if ch == quote => self.state = State::AfterAttributeValueQuoted,
            Cur::Char('&') => {
                self.return_state = self.state;
                self.state = State::CharacterReference;
            }
            Cur::Char('\0') => self.attr_value.push(REPLACEMENT),
            Cur::Char(ch) => self.attr_value.push(ch),
            Cur::Eof => self.emit_eof(),
        }
    }

    /// Shared "RCDATA / RAWTEXT / script data end tag open" logic (§13.2.5.11 etc.).
    fn end_tag_open(&mut self, c: Cur, name_state: State, back: State) {
        match c {
            Cur::Char(ch) if ch.is_ascii_alphabetic() => {
                self.tag = TagBuild { is_end: true, ..Default::default() };
                self.reconsume_in(name_state);
            }
            _ => {
                self.emit_str("</");
                self.reconsume_in(back);
            }
        }
    }

    /// Shared "appropriate end tag name" logic.
    fn end_tag_name(&mut self, c: Cur, back: State) {
        let anything_else = |t: &mut Tokenizer| {
            let s = std::mem::take(&mut t.temp);
            t.emit_str("</");
            t.emit_str(&s);
            t.reconsume_in(back);
        };
        match c {
            Cur::Char(ch) if is_ws(ch) && self.appropriate_end_tag(&self.tag.name.clone()) => {
                self.state = State::BeforeAttributeName;
            }
            Cur::Char('/') if self.appropriate_end_tag(&self.tag.name.clone()) => self.state = State::SelfClosingStartTag,
            Cur::Char('>') if self.appropriate_end_tag(&self.tag.name.clone()) => {
                let t = self.take_tag_token();
                self.emit(t);
                self.state = State::Data;
            }
            Cur::Char(ch) if ch.is_ascii_alphabetic() => {
                self.tag.name.push(ch.to_ascii_lowercase());
                self.temp.push(ch);
            }
            _ => anything_else(self),
        }
    }

    /// §13.2.5.72–73 named character references: longest match in the entity table.
    fn named_reference(&mut self) {
        let rest: String = self.input[self.pos..].iter().take(40).collect();
        let mut best: Option<(&str, &[u32])> = None;
        for &(name, cps) in NAMED {
            if rest.starts_with(name) && best.map_or(true, |(b, _)| name.len() > b.len()) {
                best = Some((name, cps));
            }
        }
        match best {
            Some((name, cps)) => {
                let legacy = !name.ends_with(';');
                let next = self.input.get(self.pos + name.chars().count()).copied();
                let attr = self.return_state_is_attribute();
                let consumed = name.chars().count();
                if legacy && attr && matches!(next, Some(ch) if ch == '=' || ch.is_ascii_alphanumeric()) {
                    // Legacy names inside attributes followed by '=' or alphanumerics are not references:
                    // the consumed characters are flushed as text.
                    self.pos += consumed;
                    self.flush_text(&format!("&{name}"));
                    self.state = self.return_state;
                    return;
                }
                self.pos += consumed;
                let s: String = cps.iter().filter_map(|&c| char::from_u32(c)).collect();
                self.flush_text(&s);
                self.state = self.return_state;
            }
            None => {
                self.temp.clear();
                self.temp.push('&');
                let t = std::mem::take(&mut self.temp);
                self.flush_text(&t);
                self.state = State::AmbiguousAmpersand;
            }
        }
    }
}

/// §13.2.5.80 table for numeric references in 0x80..=0x9F.
fn c1_replacement(c: u32) -> char {
    let r = match c {
        0x80 => 0x20AC,
        0x82 => 0x201A,
        0x83 => 0x0192,
        0x84 => 0x201E,
        0x85 => 0x2026,
        0x86 => 0x2020,
        0x87 => 0x2021,
        0x88 => 0x02C6,
        0x89 => 0x2030,
        0x8A => 0x0160,
        0x8B => 0x2039,
        0x8C => 0x0152,
        0x8E => 0x017D,
        0x91 => 0x2018,
        0x92 => 0x2019,
        0x93 => 0x201C,
        0x94 => 0x201D,
        0x95 => 0x2022,
        0x96 => 0x2013,
        0x97 => 0x2014,
        0x98 => 0x02DC,
        0x99 => 0x2122,
        0x9A => 0x0161,
        0x9B => 0x203A,
        0x9C => 0x0153,
        0x9E => 0x017E,
        0x9F => 0x0178,
        other => other,
    };
    char::from_u32(r).unwrap_or(REPLACEMENT)
}
